package com.fream.back.domain.sale.service.command;

import com.fream.back.domain.order.entity.OrderBid;
import com.fream.back.domain.order.service.query.OrderBidQueryService;
import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.product.service.productSize.ProductSizeQueryService;
import com.fream.back.domain.sale.entity.BidStatus;
import com.fream.back.domain.sale.entity.Sale;
import com.fream.back.domain.sale.entity.SaleBid;
import com.fream.back.domain.sale.repository.SaleBidRepository;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.service.query.UserQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class SaleBidCommandService {

    private final SaleBidRepository saleBidRepository;
    private final UserQueryService userQueryService;
    private final ProductSizeQueryService productSizeQueryService;
    private final SaleCommandService saleCommandService;
    private final OrderBidQueryService orderBidQueryService;
    @Transactional
    public SaleBid createSaleBid(String sellerEmail, Long productSizeId, int bidPrice,
                                 String returnAddress, String postalCode, String receiverPhone
                                , boolean isWarehouseStorage) {
        // 1. User 조회
        User seller = userQueryService.findByEmail(sellerEmail);

        // 2. ProductSize 조회
        ProductSize productSize = productSizeQueryService.findById(productSizeId)
                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));

        // 3. Sale 생성
        Sale sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);

        // 4. SaleBid 생성
        SaleBid saleBid = SaleBid.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .sale(sale) // 연관된 Sale 설정
                .build();

        // 5. SaleBid 저장
        saleBid = saleBidRepository.save(saleBid);

        // 6. Sale에 SaleBid 추가 (연관관계 설정)
        sale.assignSaleBid(saleBid);

        // 7. SaleBid 반환
        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Sale sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);
        // 1. OrderBid 조회
        OrderBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        // 3. SaleBid 생성
        SaleBid saleBid = SaleBid.builder()
                .seller(sale.getSeller()) // Sale의 판매자
                .productSize(sale.getProductSize()) // Sale의 ProductSize
                .bidPrice(orderBid.getBidPrice()) // OrderBid의 입찰 가격 사용
                .status(BidStatus.MATCHED) // 즉시 판매는 바로 매칭 상태
                .sale(sale) // Sale과 매핑
                .order(orderBid.getOrder()) // Order와 매핑
                .build();

        // 양방향 관계 설정
        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid); // Sale과 SaleBid 양방향 연관관계 설정

        // SaleBid 저장
        saleBidRepository.save(saleBid);

        // Sale ID 반환
        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {
        // SaleBid 조회
        SaleBid saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));

        // Order와 연결 여부 확인
        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }

        // Sale과 연결 여부 확인 후 삭제
        if (saleBid.getSale() != null) {
            saleCommandService.deleteSale(saleBid.getSale().getId());
        }

        // SaleBid 삭제
        saleBidRepository.delete(saleBid);
    }
}
package com.fream.back.domain.sale.service.command;

import com.fream.back.domain.notification.entity.NotificationCategory;
import com.fream.back.domain.notification.entity.NotificationType;
import com.fream.back.domain.notification.service.command.NotificationCommandService;
import com.fream.back.domain.order.entity.BidStatus;
import com.fream.back.domain.order.entity.OrderBid;
import com.fream.back.domain.order.service.query.OrderBidQueryService;
import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.sale.entity.Sale;
import com.fream.back.domain.sale.entity.SaleBankAccount;
import com.fream.back.domain.sale.entity.SaleStatus;
import com.fream.back.domain.sale.repository.SaleRepository;
import com.fream.back.domain.shipment.entity.SellerShipment;
import com.fream.back.domain.shipment.service.command.SellerShipmentCommandService;
import com.fream.back.domain.user.dto.BankAccount.BankAccountInfoDto;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.service.bankaccount.BankAccountQueryService;
import com.fream.back.domain.user.service.query.UserQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class SaleCommandService {

    private final SaleRepository saleRepository;
    private final OrderBidQueryService orderBidQueryService;
    private final NotificationCommandService notificationCommandService;
    private final UserQueryService userQueryService;
    private final SellerShipmentCommandService sellerShipmentCommandService;
    private final BankAccountQueryService bankAccountQueryService;
    private final SaleBankAccountCommandService saleBankAccountCommandService;


    @Transactional
    public Sale createInstantSale(
            Long orderBidId,
            String sellerEmail,
            String returnAddress,
            String postalCode,
            String receiverPhone
    ) {
        // 1. OrderBid 조회
        OrderBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));

        // 2. 판매자(User) 조회
        User seller = userQueryService.findByEmail(sellerEmail);

        // 3. ProductSize 정보 가져오기
        ProductSize productSize = orderBid.getProductSize();

        // 4. Sale 생성
        Sale sale = Sale.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .status(SaleStatus.PENDING_SHIPMENT) // 판매자 발송 대기 상태
                .build();

        Sale savedSale = saleRepository.save(sale);


        // 5. SaleBankAccount 생성 및 Sale에 연관 설정
        BankAccountInfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());
        SaleBankAccount saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );
        savedSale.assignSaleBankAccount(saleBankAccount);

        // 6. OrderBid와 Sale 연결
        orderBid.assignSale(savedSale);
        orderBid.updateStatus(BidStatus.MATCHED);

        // 7. 알림 전송
        User buyer = orderBid.getUser();
        notificationCommandService.createNotification(
                buyer.getId(),
                NotificationCategory.SHOPPING,
                NotificationType.BID,
                "구매 입찰에 판매자가 등록되었습니다. 확인해보세요!"
        );

        return savedSale;
    }

    @Transactional
    public Sale createSale(User seller, ProductSize productSize, String returnAddress,
                           String postalCode, String receiverPhone, boolean isWarehouseStorage) {
        // 1. BankAccount 정보 조회
        BankAccountInfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());

        // 2. Sale 생성
        Sale sale = Sale.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .isWarehouseStorage(isWarehouseStorage) // 창고 보관 여부 설정
                .status(SaleStatus.PENDING_SHIPMENT) // 초기 상태 설정
                .build();

        Sale savedSale = saleRepository.save(sale);

        // 3. SaleBankAccount 생성 및 저장
        SaleBankAccount saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );

        // 4. Sale에 SaleBankAccount 연관 설정
        savedSale.assignSaleBankAccount(saleBankAccount);

        // 5. 알림 전송
        notificationCommandService.createNotification(
                seller.getId(),
                NotificationCategory.SHOPPING,
                NotificationType.BID,
                "판매 입찰이 등록되었습니다."
        );

        return savedSale;
    }


    @Transactional
    public SellerShipment createSellerShipment(Long saleId, String courier, String trackingNumber) {
        // 1. SellerShipment 생성
        SellerShipment shipment = sellerShipmentCommandService.createSellerShipment(saleId, courier, trackingNumber);

        // 2. Sale 상태를 배송 중으로 업데이트
        updateSaleStatus(saleId, SaleStatus.IN_TRANSIT);

        return shipment;
    }

    @Transactional
    public void updateSaleStatus(Long saleId, SaleStatus newStatus) {
        Sale sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));

        // 현재 상태와 전환하려는 상태 확인
        System.out.println("현재 상태: " + sale.getStatus());
        System.out.println("전환하려는 상태: " + newStatus);
        if (!sale.getStatus().canTransitionTo(newStatus)) {
            throw new IllegalStateException("Sale 상태를 " + newStatus + "로 전환할 수 없습니다.");
        }

        sale.updateStatus(newStatus);
    }

    @Transactional
    public void deleteSale(Long saleId) {
        // Sale 조회
        Sale sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));

        // Sale 삭제
        saleRepository.delete(sale);
    }


}


package com.fream.back.domain.notification.entity;

public enum NotificationType {

    // SHOPPING 카테고리 알림 유형
    TRADE(NotificationCategory.SHOPPING, "거래 관련 알림"),
    BID(NotificationCategory.SHOPPING, "입찰 관련 알림"),
    STORAGE(NotificationCategory.SHOPPING, "보관 관련 알림"),
    FAVORITE(NotificationCategory.SHOPPING, "관심 상품 관련 알림"),
    BENEFIT(NotificationCategory.SHOPPING, "혜택 관련 알림"),
    ANNOUNCEMENT(NotificationCategory.SHOPPING, "공지사항 알림"),
    REFUND(NotificationCategory.SHOPPING, "환불 관련 알림"), // 추가: 환불 알림 유형

    // STYLE 카테고리 알림 유형
    LIKE(NotificationCategory.STYLE, "좋아요 관련 알림"),
    COMMENT(NotificationCategory.STYLE, "댓글 관련 알림"),
    FOLLOW(NotificationCategory.STYLE, "팔로우 관련 알림");

    private final NotificationCategory category;
    private final String description;

    NotificationType(NotificationCategory category, String description) {
        this.category = category;
        this.description = description;
    }

    public NotificationCategory getCategory() {
        return category;
    }

    public String getDescription() {
        return description;
    }

    /**
     * 특정 카테고리에 속하는 모든 알림 유형을 반환
     *
     * @param category 검색할 카테고리
     * @return 카테고리에 속하는 알림 유형 배열
     */
    public static NotificationType[] getTypesByCategory(NotificationCategory category) {
        if (category == null) {
            return values();
        }

        return java.util.Arrays.stream(values())
                .filter(type -> type.getCategory() == category)
                .toArray(NotificationType[]::new);
    }
}package com.fream.back.domain.notification.entity;

public enum NotificationCategory {

    SHOPPING("쇼핑 관련 알림"),
    STYLE("스타일 관련 알림");

    private final String description;

    NotificationCategory(String description) {
        this.description = description;
    }

    public String getDescription() {
        return description;
    }
}package com.fream.back.domain.product.entity;

import com.fream.back.domain.user.entity.User;
import com.fream.back.global.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Interest extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private User user; // 관심 등록한 사용자

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_color_id")
    private ProductColor productColor; // 관심 등록된 상품 색상

    // 연관관계 편의 메서드
    public void assignUser(User user) {
        if (this.user != null) {
            this.user.getInterests().remove(this);
        }
        this.user = user;
        user.getInterests().add(this);
    }

    public void unassignUser() {
        if (this.user != null) {
            this.user.getInterests().remove(this);
            this.user = null;
        }
    }

    public void assignProductColor(ProductColor productColor) {
        if (this.productColor != null) {
            this.productColor.getInterests().remove(this);
        }
        this.productColor = productColor;
        productColor.getInterests().add(this);
    }

    public void unassignProductColor() {
        if (this.productColor != null) {
            this.productColor.getInterests().remove(this);
            this.productColor = null;
        }
    }
}
